try {

const f = $input.first().json.files || [];
if (!f.length) throw new Error('Arquivo nexxusdoc_otr_n8n.json nao encontrado em Sua Area > Nexxus > NexxusDoc.');
return [{ json: { id: f[0].id } }];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[OTR: escolher estado] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const est = $('OTR: baixar estado').first().json || {};
const id = $('OTR: escolher estado').first().json.id;
const agora = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
const fs = ($input.first().json.files || []).filter(f => /^fisia_otr_1998_\d{14}\.xlsx$/i.test(f.name || ''));
fs.sort((a, b) => b.name.localeCompare(a.name));
const f = fs[0];
if (!f || f.name === est.arquivo) {
  // nada novo: so registra que conferiu a pasta (o sistema usa isso para dizer se o OTR esta em dia)
  const atual = JSON.parse(JSON.stringify(est));
  atual.ultima_execucao = agora;
  atual.mais_recente_pasta = f ? f.name : (est.arquivo || '');
  return [{ json: { novo: 'nao', id: id, conteudo: JSON.stringify(atual) } }];
}
return [{ json: { novo: 'sim', id: id, drive_id: f.id, arquivo: f.name } }];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[OTR: novo?] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}

try {

const info = $('OTR: tem arquivo novo?').first().json;
const antes = $('OTR: baixar estado').first().json || {};
const txt = v => { if (v === null || v === undefined) return ''; let s = String(v).trim(); if (/^\d+\.0$/.test(s)) s = s.slice(0, -2); return s; };
const num = v => { if (v === null || v === undefined || v === '') return null; const n = Number(String(v).replace(',', '.')); return isNaN(n) ? null : Math.round(n * 1000) / 1000; };
const chave = v => { const s = String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); const m = s.match(/^(?:[A-Z]{4}|BL|HAWB|AWB)(\d{6,}[A-Z]?)$/); return m ? m[1] : s; };
const hist = JSON.parse(JSON.stringify(antes.hist || {}));
const antesN = Object.keys(hist).length;
const m = /_(\d{14})\.xlsx$/i.exec(info.arquivo || '');
if (!m) throw new Error('Nome do OTR fora do padrao: ' + info.arquivo);
const visto = m[1];
let n = 0;
for (const it of $input.all()) {
  const r = it.json || {};
  const bol = txt(r.BOL_MAWB), po = txt(r.PURCHASE_ORDER_ID);
  if (!bol || !po) continue;
  n++;
  const ln = txt(r.PO_LINE_NUMBER).replace(/^0+/, '');
  const modo = txt(r.MODE_OF_TRANSPORT_CODE1);
  const hawb = modo !== 'VL' && modo !== '' ? txt(r.CONTR_HAWB_PRONBR) : '';
  const k = po + '|' + ln;
  if (!hist[k] || visto >= String(hist[k][6])) {
    hist[k] = [chave(bol), hawb ? chave(hawb) : '', txt(r.TCCI_BILLING_NUMBER), txt(r.MATERIAL), num(r.TOTAL_SHIPPED_QUANTITY), num(r.GROSS_WEIGHT1), visto];
  }
}
if (n < 1000) throw new Error('OTR com poucas linhas (' + n + '): arquivo incompleto; o historico anterior foi mantido.');
if (Object.keys(hist).length < antesN) throw new Error('O historico do OTR diminuiu: nada foi gravado.');
const agora = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
const novo = { versao: 2, arquivo: info.arquivo, drive_id: info.drive_id, lido_em: agora, ultima_execucao: agora, linhas: n,
               mais_recente_pasta: info.arquivo, historico_desde: antes.historico_desde || info.arquivo,
               arquivos_no_historico: (antes.arquivos_no_historico || 0) + 1, pedidos_linhas: Object.keys(hist).length, hist: hist };
return [{ json: { id: info.id, conteudo: JSON.stringify(novo) } }];

} catch (erro) {
  const m = erro && erro.message ? erro.message : (typeof erro === 'string' ? erro : JSON.stringify(erro));
  throw new Error('[OTR: montar] ' + m + (erro && erro.stack ? ' | ' + String(erro.stack).split('\n').slice(0, 4).join(' / ') : ''));
}
